choose.otherwise:
AND (


            p.pi_id = #{scopePiId}


            OR p.dept_id IN

                #{deptId}



            OR p.id IN

                #{grantedId}


        OR EXISTS (
            SELECT 1
              FROM project_member pm
             WHERE pm.project_id = p.id
               AND pm.user_id = #{scopeUserId}
               AND pm.status = 'ACTIVE'
               AND pm.valid_from <= now()
               AND (pm.valid_to IS NULL OR pm.valid_to > now())
        )

)
